<div class="page-head"><div><h3>Users</h3><p>Admin-only access control.</p></div></div><div class="cols"><section class="panel"><h3>Create user</h3><form method="post" action="<?= base_url('users/create') ?>" class="form-grid"><?= csrf_field() ?><label>Name<input name="name" required></label><label>Email<input type="email" name="email" required></label><label>Password<input type="password" name="password" minlength="8" required></label><label>Role<select name="role"><option value="user">Normal user</option><option value="admin">Admin</option></select></label><button class="primary">Create</button></form></section><section class="panel"><h3><?= count($rows) ?> accounts</h3><?php foreach($rows as $r): ?><div class="user-row"><span class="avatar"><?= strtoupper(substr($r['name'],0,1)) ?></span><div class="grow"><b><?= esc($r['name']) ?></b><small><?= esc($r['email']) ?> · <?= esc($r['role']) ?></small></div><span class="pill"><?= $r['is_active']?'Active':'Off' ?></span><?php if($r['id']!=$user['id']): ?><form method="post" action="<?= base_url('users/toggle/'.$r['id']) ?>"><?= csrf_field() ?><button class="link"><?= $r['is_active']?'Disable':'Enable' ?></button></form><?php endif; ?></div><?php endforeach; ?></section></div>